/*{
  "DESCRIPTION": "Gently falling snow with twinkling lights",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "snowColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "skyColor", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.1, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 2.0, "DEFAULT": 0.3 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.8 }
  ]
}*/

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  float yOffset = mod(TIME * speed, 2.0);

  vec2 snowUV = uv * vec2(8.0, 6.0);
  snowUV.y += yOffset * 6.0;

  float snowNoise = noise(snowUV);
  snowNoise += noise(snowUV * 2.0) * 0.5;
  snowNoise = smoothstep(0.3, 0.7, snowNoise * density);

  float twinkle = 0.5 + 0.5 * sin(TIME * 3.0 + hash(floor(snowUV)) * 6.28);
  snowNoise *= mix(0.5, 1.0, twinkle);

  vec3 col = mix(skyColor.rgb, snowColor.rgb, snowNoise);

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Fire rises from the bottom with flickering flames",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "colorHot", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.0, 1.0] },
    { "NAME": "colorCool", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] }
  ]
}*/

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

float noise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  float h = uv.y;
  float w = uv.x;

  if (RENDERSIZE.y < 2.0) {
    h = uv.x;
    w = uv.y;
  }

  float t = TIME * speed * 0.5;
  float flame = noise(w * scale + t * 1.2) * noise(w * scale * 0.5 - t * 0.7);
  flame += noise(w * scale * 2.0 + t * 0.9) * 0.5;

  float rise = (h - 0.2) * 4.0 + t * 0.8;
  float lift = sin(rise + flame * 3.0) * 0.3 + 0.3;

  float intensity = smoothstep(0.0, 0.1, h) * smoothstep(1.0, 0.3, h);
  intensity *= flame * lift * 1.5;

  vec3 fireColor = mix(colorCool.rgb, colorHot.rgb, smoothstep(0.2, 0.8, flame));

  gl_FragColor = vec4(fireColor * intensity, 1.0);
}

/*{
  "DESCRIPTION": "Candy cane stripes scrolling diagonally across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "stripeWidth", "TYPE": "float", "MIN": 0.01, "MAX": 0.5, "DEFAULT": 0.1 },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float diagPos = uv.x + uv.y - TIME * speed * 0.5;
  float stripe = fract(diagPos / (stripeWidth * 2.0));
  float band = step(stripe, stripeWidth / (stripeWidth * 2.0));

  gl_FragColor = vec4(mix(colorA.rgb, colorB.rgb, band), 1.0);
}

/*{
  "DESCRIPTION": "Smooth fade between colors across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  float phase = mod(TIME * speed * 0.5, 3.0);

  vec3 color;
  if (phase < 1.0) {
    color = mix(colorA.rgb, colorB.rgb, smoothstep(0.0, 1.0, phase));
  } else if (phase < 2.0) {
    color = mix(colorB.rgb, colorC.rgb, smoothstep(1.0, 2.0, phase));
  } else {
    color = mix(colorC.rgb, colorA.rgb, smoothstep(2.0, 3.0, phase));
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Twinkling stars scattered across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "starColor", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "backgroundColor", "TYPE": "color", "DEFAULT": [0.0, 0.0, 0.2, 1.0] },
    { "NAME": "twinklSpeed", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "starDensity", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.8 }
  ]
}*/

float hash(vec2 p) {
  float h = dot(p, vec2(127.1, 311.7));
  return fract(sin(h) * 43758.5453123);
}

void main() {
  vec2 uv = isf_FragNormCoord;
  vec2 gridUv = uv * starDensity * 8.0;
  vec2 gridCell = floor(gridUv);
  vec2 gridPos = fract(gridUv);

  float closestDist = 2.0;
  float twinkle = 0.0;

  for (int dy = -1; dy <= 1; dy++) {
    for (int dx = -1; dx <= 1; dx++) {
      vec2 cell = gridCell + vec2(float(dx), float(dy));
      vec2 cellSeed = cell + vec2(0.5);

      float randomX = hash(cellSeed * 1.23);
      float randomY = hash(cellSeed * 4.56);
      float randomTwinkle = hash(cellSeed * 7.89);

      vec2 starPos = vec2(randomX, randomY);
      float dist = length(gridPos - starPos);

      if (dist < closestDist) {
        closestDist = dist;
        float phase = randomTwinkle * 6.28318 + TIME * twinklSpeed;
        twinkle = sin(phase) * 0.5 + 0.5;
        twinkle *= smoothstep(0.15, 0.0, dist);
      }
    }
  }

  vec3 color = mix(backgroundColor.rgb, starColor.rgb, twinkle);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Chasing lights running continuously along the roofline",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.02, "MAX": 0.3, "DEFAULT": 0.1 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float chase_pos = mod(uv.x - TIME * speed * 0.5, 1.0);

  float dist = abs(chase_pos - 0.5);
  float light = smoothstep(width, 0.0, dist);

  vec3 color = mix(colorA.rgb, colorB.rgb, light);

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Swirling plasma effect with animated color waves",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [1.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  // Center and scale coordinates
  vec2 pos = (uv - 0.5) * scale;

  // Swirling motion using angle and radius
  float angle = atan(pos.y, pos.x);
  float radius = length(pos);

  // Create swirling waves
  float swirl1 = sin(angle * 3.0 + TIME * speed - radius * 2.0);
  float swirl2 = cos(angle * 2.0 - TIME * speed * 0.7 + radius * 1.5);
  float swirl3 = sin(radius * 4.0 - angle + TIME * speed * 0.5);

  // Combine swirls into a single value
  float pattern = (swirl1 + swirl2 + swirl3) * 0.333;

  // Map pattern to color ranges
  float colorMix1 = fract(pattern + TIME * speed * 0.25);
  float colorMix2 = fract(pattern - TIME * speed * 0.25);

  // Blend three colors based on pattern
  vec3 col = mix(colorA.rgb, colorB.rgb, smoothstep(-1.0, 1.0, swirl1));
  col = mix(col, colorC.rgb, smoothstep(-1.0, 1.0, swirl2));

  // Add brightness variation based on radius and time
  float brightness = 0.5 + 0.5 * sin(radius * 3.0 + TIME * speed);
  col *= brightness;

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Rainbow colors sweep horizontally across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "width", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float sweep = mod(uv.x + TIME * speed * 0.5 - uv.y * width, 1.0);

  vec3 col;
  if (sweep < 0.166666) {
    col = mix(vec3(1.0, 0.0, 0.0), vec3(1.0, 0.5, 0.0), sweep * 6.0);
  } else if (sweep < 0.333333) {
    col = mix(vec3(1.0, 0.5, 0.0), vec3(1.0, 1.0, 0.0), (sweep - 0.166666) * 6.0);
  } else if (sweep < 0.5) {
    col = mix(vec3(1.0, 1.0, 0.0), vec3(0.0, 1.0, 0.0), (sweep - 0.333333) * 6.0);
  } else if (sweep < 0.666666) {
    col = mix(vec3(0.0, 1.0, 0.0), vec3(0.0, 0.0, 1.0), (sweep - 0.5) * 6.0);
  } else if (sweep < 0.833333) {
    col = mix(vec3(0.0, 0.0, 1.0), vec3(0.75, 0.0, 1.0), (sweep - 0.666666) * 6.0);
  } else {
    col = mix(vec3(0.75, 0.0, 1.0), vec3(1.0, 0.0, 0.0), (sweep - 0.833333) * 6.0);
  }

  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Lights pulse to a steady beat with color cycling",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "beatFrequency", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "sharpness", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float beat = mod(TIME * beatFrequency, 3.0);
  float pulse = sin(TIME * beatFrequency * 3.14159265359) * 0.5 + 0.5;
  pulse = pow(pulse, sharpness);

  vec3 color;
  if (beat < 1.0) {
    color = mix(colorA.rgb, colorB.rgb, beat);
  } else if (beat < 2.0) {
    color = mix(colorB.rgb, colorC.rgb, beat - 1.0);
  } else {
    color = mix(colorC.rgb, colorA.rgb, beat - 2.0);
  }

  color = mix(vec3(0.1), color, pulse);

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "American flag waving with stars and stripes",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "waveAmplitude", "TYPE": "float", "MIN": 0.0, "MAX": 0.3, "DEFAULT": 0.1 },
    { "NAME": "waveFrequency", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 3.0, "DEFAULT": 1.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  float wavePhase = TIME * speed;
  float wave = sin(uv.y * waveFrequency * 3.14159 + wavePhase) * waveAmplitude;
  float distortedX = uv.x + wave * (1.0 - uv.x);

  vec3 color = vec3(0.0);

  if (distortedX < 0.0) {
    color = vec3(0.0);
  } else if (distortedX < 0.2) {
    float starY = uv.y * 9.0;
    float starX = distortedX * 50.0;
    float starPattern = mod(floor(starX) + floor(starY), 2.0);
    float starDot = sin(starX * 3.14159) * sin(starY * 3.14159);
    if (starPattern > 0.5 && starDot > 0.5) {
      color = vec3(1.0, 1.0, 1.0);
    } else {
      color = vec3(0.0, 0.2, 0.5);
    }
  } else {
    float stripeIndex = floor(uv.y * 13.0);
    float isRed = mod(stripeIndex, 2.0);
    if (isRed > 0.5) {
      color = vec3(1.0, 0.0, 0.0);
    } else {
      color = vec3(1.0, 1.0, 1.0);
    }
  }

  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Spooky green fog drifting across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "fogColor", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 3.0, "DEFAULT": 1.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 5.0, "DEFAULT": 2.0 }
  ]
}*/

float hash(float n) {
  return fract(sin(n) * 43758.5453123);
}

float noise(float x) {
  float i = floor(x);
  float f = fract(x);
  f = f * f * (3.0 - 2.0 * f);
  return mix(hash(i), hash(i + 1.0), f);
}

void main() {
  vec2 uv = isf_FragNormCoord;

  float fogEffect = 0.0;
  float baseFreq = scale;
  float amp = 1.0;

  for(int i = 0; i < 4; i++) {
    float freq = baseFreq * pow(2.0, float(i));
    float noiseSample = noise(uv.x * freq + TIME * speed * 0.5 - float(i) * 0.3);
    fogEffect += noiseSample * amp;
    amp *= 0.5;
  }

  fogEffect = pow(fogEffect * density, 0.8);
  fogEffect = clamp(fogEffect, 0.0, 1.0);

  float verticalGradient = smoothstep(1.2, -0.2, uv.y);
  fogEffect *= verticalGradient;

  vec3 finalColor = mix(vec3(0.0, 0.0, 0.0), fogColor.rgb, fogEffect);

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "A spinning tunnel of colored lights that rotates around the center as you fly through it",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.0, 0.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "segments", "TYPE": "float", "MIN": 3.0, "MAX": 16.0, "DEFAULT": 8.0 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord - 0.5;
  float angle = atan(uv.y, uv.x);
  float radius = length(uv);

  float tunnelDepth = fract(radius * 3.0 - TIME * speed * 0.5);
  float segmentAngle = fract((angle / 6.28318530718) + TIME * speed * 0.3);
  float whichSegment = mod(floor(segmentAngle * segments), 3.0);

  float brightness = 1.0 - smoothstep(0.35, 0.5, radius);
  brightness *= smoothstep(0.0, 0.1, tunnelDepth) * smoothstep(1.0, 0.85, tunnelDepth);

  vec3 col;
  if (whichSegment < 1.0) {
    col = colorA.rgb;
  } else if (whichSegment < 2.0) {
    col = colorB.rgb;
  } else {
    col = colorC.rgb;
  }

  col *= brightness;
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Ocean waves rolling across the display with animated water motion",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorDeep", "TYPE": "color", "DEFAULT": [0.0, 0.2, 0.6, 1.0] },
    { "NAME": "colorShallow", "TYPE": "color", "DEFAULT": [0.0, 0.8, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "wavelength", "TYPE": "float", "MIN": 0.1, "MAX": 3.0, "DEFAULT": 1.0 },
    { "NAME": "waveHeight", "TYPE": "float", "MIN": 0.0, "MAX": 1.0, "DEFAULT": 0.4 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;
  float height = RENDERSIZE.y;

  // For very short displays (roof line), use horizontal wave instead of vertical
  float animCoord = (height < 2.0) ? uv.x : uv.y;

  // Create rolling wave using sine with horizontal scrolling
  float wave = sin((animCoord - TIME * speed * 0.5) * wavelength * 6.28318) * waveHeight;

  // Add secondary wave for texture
  float wave2 = sin((animCoord * 2.0 - TIME * speed * 0.3) * wavelength * 3.14159) * waveHeight * 0.5;

  // Combine waves
  float totalWave = wave + wave2;

  // Map wave position to color: deep at bottom, shallow at top
  float wavePos = (height < 2.0) ? (1.0 - uv.y) : uv.y;
  float blendFactor = smoothstep(-0.3, 0.7, wavePos + totalWave);

  vec3 waterColor = mix(colorDeep.rgb, colorShallow.rgb, blendFactor);

  gl_FragColor = vec4(waterColor, 1.0);
}

/*{
  "DESCRIPTION": "Slow-moving lava lamp blobs that rise and fall with organic motion",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 2.0, "DEFAULT": 0.5 },
    { "NAME": "scale", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.5 }
  ]
}*/

void main() {
  vec2 uv = isf_FragNormCoord;

  // Handle tall vs short displays
  float animCoord = uv.x;
  if (RENDERSIZE.y < 2.0) {
    animCoord = uv.x;
  } else {
    animCoord = uv.y;
  }

  // Create multiple overlapping blob positions
  float blob1 = sin(TIME * speed * 0.3 + uv.x * 3.0) * 0.5 + 0.5;
  float blob2 = sin(TIME * speed * 0.25 - uv.x * 2.5 + 2.0) * 0.5 + 0.5;
  float blob3 = sin(TIME * speed * 0.35 + uv.x * 2.0 + 4.0) * 0.5 + 0.5;

  // Distance to blob centers
  float dist1 = abs(animCoord - blob1);
  float dist2 = abs(animCoord - blob2);
  float dist3 = abs(animCoord - blob3);

  // Smooth blob shapes with organic falloff
  float radius = 0.15 / scale;
  float blob = smoothstep(radius + 0.05, radius - 0.05, dist1)
             + smoothstep(radius + 0.08, radius - 0.08, dist2) * 0.7
             + smoothstep(radius + 0.06, radius - 0.06, dist3) * 0.6;

  blob = clamp(blob, 0.0, 1.0);

  // Color based on position and blob intensity
  float colorMix = fract(animCoord * 2.0 + TIME * speed * 0.1);
  vec3 color = mix(colorA.rgb, colorB.rgb, colorMix);

  // Blend with black background
  vec3 finalColor = mix(vec3(0.0), color, blob);

  gl_FragColor = vec4(finalColor, 1.0);
}

/*{
  "DESCRIPTION": "Alternating flashes between two colors",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.0, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 2.0 }
  ]
}*/

void main() {
  float flash = step(0.5, fract(TIME * speed * 0.5));
  vec3 color = mix(colorA.rgb, colorB.rgb, flash);
  gl_FragColor = vec4(color, 1.0);
}

/*{
  "DESCRIPTION": "Green streaks fall like digital rain across the display",
  "CREDIT": "webXLights shader assistant",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "rainColor", "TYPE": "color", "DEFAULT": [0.0, 1.0, 0.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.0, "MAX": 4.0, "DEFAULT": 1.5 },
    { "NAME": "density", "TYPE": "float", "MIN": 0.1, "MAX": 1.0, "DEFAULT": 0.6 },
